import math

def is_power_of_two(n):
    if n <= 0:
        return False
    return (n & (n - 1) == 0)

solutions = []
for x in range(4, 21):
    val = x**3 + x - 2
    if is_power_of_two(val):
        k = int(math.log2(val))
        solutions.append((x, k))

print(solutions)
